#!/usr/bin/env python3
'''Standalone CPU conceptual check for K-FW-001.
It tests a mode manifest, an inference-to-ordinary conversion state,
a consumer oracle, and logical-versus-physical storage accounting.
It imports only sys, uses no project code, and does not touch files.
'''
import sys

MIB = 1024 * 1024


class ModeViolation(Exception):
    pass


class ConversionViolation(Exception):
    pass


class ConsumerViolation(Exception):
    pass


class Module:
    def __init__(self, name, cls, training=True, sensitive=True, children=None):
        self.name = name
        self.cls = cls
        self.training = bool(training)
        self.sensitive = bool(sensitive)
        self.children = list(children) if children else []


def walk(root):
    yield root
    for child in root.children:
        for node in walk(child):
            yield node


def prepare_mode(root, spec):
    live = {m.name: m for m in walk(root)}
    sensitive = {m.name for m in walk(root) if m.sensitive}
    if set(spec.keys()) != sensitive:
        raise ModeViolation('spec must exactly cover mode-sensitive modules')
    for name in spec:
        live[name].training = bool(spec[name])
    entries = tuple((m.name, m.cls, bool(m.training))
                    for m in walk(root) if m.sensitive)
    return {'entries': entries}


def validate_frozen(root, sealed):
    live = {m.name: m for m in walk(root)}
    sensitive = {m.name for m in walk(root) if m.sensitive}
    sealed_names = {entry[0] for entry in sealed['entries']}
    if sealed_names != sensitive:
        raise ModeViolation('manifest coverage changed')
    for name, expected_class, expected_training in sealed['entries']:
        module = live.get(name)
        if module is None:
            raise ModeViolation('missing module ' + name)
        if module.cls != expected_class:
            raise ModeViolation('class changed ' + name)
        if bool(module.training) != expected_training:
            raise ModeViolation('mode changed ' + name)
    return True


def validate_root_only(root, sealed):
    root_expected = None
    for name, cls, expected in sealed['entries']:
        if name == 'root':
            root_expected = expected
    if root_expected is None:
        raise ModeViolation('no root entry')
    return bool(root.training) == root_expected


class WorkerCtx:
    def __init__(self):
        self.grad = True
        self.depth = 0


def push_mode(ctx, kind):
    saved = (ctx.grad, ctx.depth)
    if kind == 'record':
        if ctx.depth > 0:
            raise ConversionViolation('record inside inference')
        ctx.grad = True
    elif kind == 'no_grad':
        ctx.grad = False
    elif kind == 'inference':
        ctx.depth += 1
        ctx.grad = False
    else:
        raise ConversionViolation('bad mode')
    return saved


def pop_mode(ctx, saved):
    ctx.grad, ctx.depth = saved


class TensorState:
    def __init__(self, data, is_inference, storage_id, origin,
                 model_graph=False, copy_event=None):
        self.data = tuple(data)
        self.is_inference = bool(is_inference)
        self.storage_id = storage_id
        self.origin = origin
        self.model_graph = bool(model_graph)
        self.copy_event = copy_event


def forward_inference(ctx, data, storage_id):
    saved = push_mode(ctx, 'inference')
    try:
        return TensorState(data, True, storage_id, 'inference',
                           model_graph=False)
    finally:
        pop_mode(ctx, saved)


def materialize_outside_inference(ctx, raw, new_storage_id):
    if ctx.depth != 0:
        raise ConversionViolation('outer inference context still active')
    if not raw.is_inference:
        raise ConversionViolation('source is not an inference tensor')
    saved = push_mode(ctx, 'no_grad')
    try:
        out = TensorState(raw.data, False, new_storage_id,
                          'materialized_after_inference',
                          model_graph=False, copy_event='copy-complete')
    finally:
        pop_mode(ctx, saved)
    if out.storage_id == raw.storage_id:
        raise ConversionViolation('materialized tensor aliases source storage')
    return out


def materialize_inside_inference_faulty(ctx, raw, new_storage_id):
    if ctx.depth <= 0:
        raise ConversionViolation('negative control requires inference ctx')
    return TensorState(raw.data, True, new_storage_id,
                       'clone_inside_inference',
                       model_graph=False, copy_event='copy-complete')


def validate_consumer(tensor, grad_scope):
    if tensor.is_inference:
        raise ConsumerViolation('inference tensor cannot enter autograd')
    if grad_scope == 'postprocess_only':
        if tensor.origin not in ('ordinary', 'materialized_after_inference'):
            raise ConsumerViolation('unknown postprocess provenance')
    elif grad_scope == 'through_model':
        if not tensor.model_graph:
            raise ConsumerViolation('model graph was not recorded')
    else:
        raise ConsumerViolation('bad grad scope')
    return True


def validate_consumer_faulty(tensor, grad_scope):
    return True


class View:
    def __init__(self, storage_id, n_elem, bytes_per_elem, capacity_bytes):
        self.storage_id = storage_id
        self.n_elem = n_elem
        self.bytes_per_elem = bytes_per_elem
        self.capacity_bytes = capacity_bytes


def logical_payload(views, meta_per_tensor=16):
    return (sum(v.n_elem * v.bytes_per_elem for v in views)
            + meta_per_tensor * len(views))


def retained_unique(views):
    capacities = {}
    for view in views:
        old = capacities.get(view.storage_id)
        if old is None or view.capacity_bytes > old:
            capacities[view.storage_id] = view.capacity_bytes
    return sum(capacities.values())


def retained_per_view_faulty(views):
    return sum(v.capacity_bytes for v in views)


def main():
    failures = []

    def check(condition, message):
        if condition:
            print('OK ' + message)
        else:
            print('FAIL ' + message)
            failures.append(message)

    def obs(message):
        print('OBS ' + message)

    model = Module('root', 'Root', True, True, [
        Module('dropout', 'Dropout', True),
        Module('norm', 'BatchNorm', True),
        Module('linear', 'Linear', True),
    ])
    uniform_eval = {m.name: False for m in walk(model) if m.sensitive}
    sealed = prepare_mode(model, uniform_eval)
    check(validate_frozen(model, sealed), 'uniform eval mode manifest validates')

    model.children[0].training = True
    rejected = False
    try:
        validate_frozen(model, sealed)
    except ModeViolation:
        rejected = True
    check(rejected, 'manifest rejects root eval with dropout train')
    check(validate_root_only(model, sealed),
          'negative control: root-only check accepts child mode error')

    model_mixed = Module('root', 'Root', True, True, [
        Module('dropout', 'Dropout', True),
        Module('norm', 'BatchNorm', True),
        Module('linear', 'Linear', True),
    ])
    mixed_spec = {m.name: False for m in walk(model_mixed) if m.sensitive}
    mixed_spec['dropout'] = True
    mixed_sealed = prepare_mode(model_mixed, mixed_spec)
    check(validate_frozen(model_mixed, mixed_sealed),
          'explicit mixed mode is accepted by the full manifest')
    obs('sealed uniform entries=' + repr(sealed['entries']))

    ctx = WorkerCtx()
    saved_inference = push_mode(ctx, 'inference')
    saved_no_grad = push_mode(ctx, 'no_grad')
    pop_mode(ctx, saved_no_grad)
    check(ctx.grad is False and ctx.depth == 1,
          'leaving no_grad restores inference context')
    pop_mode(ctx, saved_inference)
    check(ctx.grad is True and ctx.depth == 0,
          'nested contexts restore grad and depth')

    ctx_fail = WorkerCtx()
    failed_saved = push_mode(ctx_fail, 'inference')
    try:
        try:
            raise RuntimeError('forward failed')
        finally:
            pop_mode(ctx_fail, failed_saved)
    except RuntimeError:
        pass
    check(ctx_fail.depth == 0, 'finally restores inference depth on failure')

    ctx2 = WorkerCtx()
    raw = forward_inference(ctx2, [1, 2, 3], 100)
    check(ctx2.depth == 0 and raw.is_inference,
          'forward produces inference tensor and exits local region')
    out = materialize_outside_inference(ctx2, raw, 200)
    check((not out.is_inference) and out.storage_id != raw.storage_id,
          'ordinary storage is created outside inference with no alias')
    check(validate_consumer(out, 'postprocess_only'),
          'ordinary materialized output is accepted for postprocess autograd')

    through_rejected = False
    try:
        validate_consumer(out, 'through_model')
    except ConsumerViolation:
        through_rejected = True
    check(through_rejected,
          'materialized output is rejected when model graph is required')

    ctx3 = WorkerCtx()
    bad_saved = push_mode(ctx3, 'inference')
    fake = materialize_inside_inference_faulty(ctx3, raw, 300)
    fake_rejected = False
    try:
        validate_consumer(fake, 'postprocess_only')
    except ConsumerViolation:
        fake_rejected = True
    check(fake_rejected,
          'consumer rejects an inside-inference clone despite claimed copy')
    check(validate_consumer_faulty(fake, 'postprocess_only'),
          'negative control: faulty consumer accepts inference tensor')
    pop_mode(ctx3, bad_saved)

    ctx4 = WorkerCtx()
    outer_saved = push_mode(ctx4, 'inference')
    outer_rejected = False
    try:
        materialize_outside_inference(ctx4, raw, 400)
    except ConversionViolation:
        outer_rejected = True
    check(outer_rejected, 'materializer rejects an outer inference context')
    pop_mode(ctx4, outer_saved)

    record_tensor = TensorState([4, 5], False, 500, 'record_forward',
                                model_graph=True, copy_event='done')
    check(validate_consumer(record_tensor, 'through_model'),
          'recorded model tensor carries the model graph')

    n_elem = 8 * 1024 * 4096
    independent = [View('s' + str(i), n_elem, 2, 64 * MIB)
                   for i in range(12)]
    logical = logical_payload(independent)
    physical = retained_unique(independent)
    check(logical == 805306560, 'logical payload with 12 metadata entries')
    check(physical == 805306368, '12 independent 64 MiB storages')
    check(sum(v.n_elem * v.bytes_per_elem for v in independent) == physical,
          'independent compact storage makes logical data equal payload')
    obs('12 independent logical=' + str(logical) + ' physical=' + str(physical))

    shared_small = [View('big', 1, 2, 64 * MIB) for _ in range(12)]
    check(logical_payload(shared_small) < retained_unique(shared_small),
          'small slices can retain far more than their logical bytes')
    check(retained_unique(shared_small) == 64 * MIB,
          'shared storage is counted once for small slices')
    check(retained_per_view_faulty(shared_small) > retained_unique(shared_small),
          'negative control: per-view capacity sum double counts shared storage')

    shared_full = [View('big', n_elem, 2, 64 * MIB) for _ in range(12)]
    check(logical_payload(shared_full) == 805306560,
          'shared full views produce a large logical sum')
    check(retained_unique(shared_full) == 64 * MIB,
          'shared full views retain one physical storage')
    check(retained_per_view_faulty(shared_full) == 768 * MIB,
          'negative control: per-view sum reports 768 MiB for one storage')
    obs('shared full logical=' + str(logical_payload(shared_full))
        + ' physical=' + str(retained_unique(shared_full)))

    if failures:
        print('RESULT: FAIL (' + str(len(failures)) + ' checks failed)')
        return 1
    print('RESULT: PASS (mode manifest, conversion state, consumer oracle, storage accounting; negative controls detected)')
    return 0


if __name__ == '__main__':
    sys.exit(main())
